arrows.css:
.hesperiden.sr7-arrows {
	cursor:pointer;
	background:##bg-color##;
	width:##bg-size##px;
	height:##bg-size##px;
	position:absolute;
	display:block;
	z-index:1000;
    border-radius: 50%;
}
.hesperiden.sr7-arrows.sr7-touchhover {
	background:##hover-bg-color##;
}
.hesperiden.sr7-arrows:before {
	font-family: 'revicons';
	font-size:##arrow-size##px;
	color:##arrow-color##;
	display:block;
	line-height: ##bg-size##px;
	text-align: center;
}
.hesperiden.sr7-arrows.sr7-leftarrow:before {
	content: '##left-icon##';
    margin-left:-3px;
}
.hesperiden.sr7-arrows.sr7-rightarrow:before {
	content: '##right-icon##';
    margin-right:-3px;
}

bullets.css:
.hermes.sr7-bullets {
}

.hermes .sr7-bullet {
    overflow:hidden;
    border-radius:50%;
    width:##bullet-size##px;
    height:##bullet-size##px;
    background-color: rgba(0, 0, 0, 0);
    box-shadow: inset 0 0 0 ##border##px ##bullet-color##;
    -webkit-transition: background 0.3s ease;
    transition: background 0.3s ease;
    position:absolute;
}

.hermes .sr7-bullet.sr7-touchhover {
	  background-color: ##bullet-hover##;
}
.hermes .sr7-bullet:after {
  content: ' ';
  position: absolute;
  bottom: 0;
  height: 0;
  left: 0;
  width: 100%;
  background-color: ##bullet-color##;
  box-shadow: 0 0 1px ##bullet-color##;
  -webkit-transition: height 0.3s ease;
  transition: height 0.3s ease;
}
.hermes .sr7-bullet.selected:after {
  height:100%;
}

